css_extra:
/* fonte das informações, discreta, alinhada à direita */
.fonte { font-size:12.5px; color:var(--tx-apoio); text-align:right; line-height:1.3; margin-top:-4px }
.slbd.g > .fonte, .slbd.g > div > .fonte { margin-top:-8px }
/* capa */
#s1 .capa .esq h1 { font-size:38px }
#s1 .capa .esq h1 span { display:block; font-size:.6em; font-weight:600; line-height:1.3; margin-top:8px; letter-spacing:-.2px; color:var(--destaque) }
#s1 .capa .esq .sub { font-size:15.5px }
#s1 .capa .esq .sub b { color:#fff }
/* roteiro */
#s2 .lin div { font-size:17px }
#s2 .lin span { color:var(--tx-apoio) }
#s2 .lin { padding:9px 18px }
#s2 .card.vd p { font-size:15.5px }
/* mapa obstáculo → pilar (slide 4) */
.mapa { display:grid; grid-template-rows:auto repeat(3,1fr); gap:10px; flex:1; min-height:0 }
.mapa .ln { display:grid; grid-template-columns:1fr 44px 0.82fr; align-items:stretch; gap:0 }
.mapa .cab { font-size:12px; font-weight:800; letter-spacing:.16em; text-transform:uppercase; color:var(--tx-apoio); align-self:end }
.mapa .cab.d { color:var(--vd-tx) }
.mapa .obs { background:var(--card-bg); border:1px solid var(--linha); border-radius:14px; padding:10px 16px; display:flex; flex-direction:column; justify-content:center }
.mapa .obs b { color:var(--az); font-size:1.02em }
.mapa .obs span { color:var(--tx-apoio); font-size:15.5px; line-height:1.35; margin-top:2px }
.mapa .seta { display:flex; align-items:center; justify-content:center; color:var(--ve); font-size:26px; font-weight:800 }
.mapa .pil { background:var(--vd-bg); border:1px solid var(--vd-bd); border-radius:14px; padding:10px 16px; display:flex; align-items:center; gap:12px; font-weight:700; color:var(--vd-tx) }
.n-bola { flex-shrink:0; width:30px; height:30px; border-radius:50%; background:var(--ve); color:#fff; font-weight:800; display:inline-flex; align-items:center; justify-content:center; font-size:15px }
/* laço do AHE (slide 5) */
.laco { display:grid; grid-template-columns:1fr 34px 1fr 34px 1fr 34px 1fr; grid-template-rows:1fr 28px 1fr; flex:1; min-height:0 }
.laco .no { background:var(--card-bg); border:1px solid var(--linha); border-radius:14px; padding:9px 12px; display:flex; flex-direction:column; justify-content:center; text-align:center; line-height:1.3 }
.laco .no b { color:var(--az); font-size:1.1em }
.laco .no span { font-size:15.5px; color:var(--tx-apoio); margin-top:3px }
.laco .no.esc { background:linear-gradient(135deg,var(--az),var(--bem2)); border:0 }
.laco .no.esc b { color:#fff } .laco .no.esc span { color:#DCE3EE }
.laco .no.vd { background:var(--vd-bg); border-color:var(--vd-bd) } .laco .no.vd b { color:var(--vd-tx) }
.laco .sh, .laco .sv { display:flex; align-items:center; justify-content:center; color:var(--ve); font-weight:800; font-size:22px }
.pilares { display:grid; grid-template-columns:repeat(3,1fr); gap:12px }
.pilares div { display:flex; align-items:center; gap:10px; background:var(--azc); border:1px solid var(--azc-bd); border-radius:12px; padding:8px 12px; font-weight:700; color:var(--bem2); font-size:15.5px; line-height:1.3 }
/* componentes do NexAU (slide 6) */
.tiles { display:grid; grid-template-columns:repeat(4,1fr); grid-template-rows:1fr 1fr; gap:12px; flex:1.25 1 0 }
#s6 .col > .grade { flex:1 1 0 }
#s6 .card { justify-content:center }
.tiles .tl { background:var(--card-bg); border:1px solid var(--linha); border-radius:12px; padding:10px 14px; display:flex; gap:12px; align-items:center; min-height:0 }
.tiles .tl b { display:block; color:var(--az); font-size:17px; line-height:1.25 }
.tiles .tl > div span { display:block; color:var(--tx-apoio); font-size:15px; line-height:1.3; margin-top:2px }
.tiles .tl .n-bola { width:30px; height:30px; font-size:15px }
.tiles .tl.esc { background:linear-gradient(135deg,var(--az),var(--bem2)); border:0; align-items:center }
.tiles .tl.esc b { color:#fff } .tiles .tl.esc > div span { color:#DCE3EE }
/* funil do Agent Debugger (slide 7) */
.funil { display:flex; flex-direction:column; align-items:center; gap:6px; flex:1; justify-content:center }
.funil .cam { border-radius:14px; padding:20px 22px; text-align:center; line-height:1.3 }
.funil .cam b { display:block; font-size:1.2em } .funil .cam span { display:block; font-size:16px; margin-top:4px }
.funil .f1 { width:100%; background:linear-gradient(135deg,var(--az),var(--bem2)); color:#fff } .funil .f1 span { color:#DCE3EE }
.funil .f2 { width:82%; background:var(--azc); border:1px solid var(--azc-bd); color:var(--az) } .funil .f2 span { color:var(--tx-apoio) }
.funil .f3 { width:64%; background:var(--vd-bg); border:2px solid var(--ve); color:var(--vd-tx) } .funil .f3 span { color:var(--vd-tx) }
.funil .ar { color:var(--ve); font-weight:800; font-size:24px; line-height:1 }
/* cadeia do manifesto (slide 8) */
.cadeia { display:grid; grid-template-columns:1fr 30px 1fr 30px 1fr 30px 1.15fr; align-items:stretch }
.cadeia .el { border-radius:12px; padding:14px 12px; text-align:center; font-weight:700; display:flex; flex-direction:column; justify-content:center; line-height:1.3; background:var(--card-bg); border:1px solid var(--linha); color:var(--az) }
.cadeia .el span { font-weight:400; font-size:15px; color:var(--tx-apoio); margin-top:3px }
.cadeia .el.fim { background:linear-gradient(135deg,var(--az),var(--bem2)); color:#fff; border:0 } .cadeia .el.fim span { color:#DCE3EE }
.cadeia .sh { display:flex; align-items:center; justify-content:center; color:var(--ve); font-weight:800; font-size:20px }
/* etapas do algoritmo (slide 9) */
.etapas { display:grid; grid-template-columns:repeat(3,1fr); grid-template-rows:1fr 1fr; gap:12px; flex:1; min-height:0; counter-reset:et }
.etapas .ep { background:var(--card-bg); border:1px solid var(--linha); border-radius:14px; padding:14px 20px; display:flex; flex-direction:column; justify-content:center }
.etapas .ep h4 { display:flex; align-items:center; gap:10px; font-size:1.25em; color:var(--az); margin-bottom:6px }
.etapas .ep p { margin:0; font-size:18px; color:var(--tx-apoio); line-height:1.4 }
.etapas .ep.at { background:var(--vd-bg); border-color:var(--vd-bd) } .etapas .ep.at h4 { color:var(--vd-tx) }
/* configuração (slide 10) */
#s10 .tb2 { font-size:15.5px } #s10 .tb2 th { font-size:15.5px }
#s10 .tb2 td, #s10 .tb2 th { padding:6px 12px }
#s10 .slbd.g .tb2 tr > *:nth-child(n+2) { text-align:left }
#s10 .tb2 td:first-child { font-weight:700; color:var(--az); width:28% }
#s10 .lin div { font-size:15.5px } #s10 .lin { padding:9px 14px }
/* gráficos e kpis dos experimentos */
#s11 .kpi b, #s12 .kpi b, #s15 .kpi b { font-size:26px }
#s11 .kpi > div, #s15 .kpi > div { padding:10px 14px }
#s11 .card li, #s13 .card li, #s14 .card li, #s15 .card li { font-size:16px; margin:4px 0 }
#s12 .tb2 { margin:0 } #s12 .tb2 td, #s12 .tb2 th { padding:7px 12px }
#s12 .card li { font-size:16px; margin:4px 0 }
/* análise crítica (slide 16) */
.criticas { display:grid; grid-template-columns:repeat(6,1fr); grid-template-rows:1fr 1fr; gap:12px; flex:1; min-height:0 }
.criticas .cr { grid-column:span 2; background:var(--card-bg); border:1px solid var(--linha); border-radius:14px; padding:14px 20px; display:flex; flex-direction:column; justify-content:center }
.criticas .cr:nth-child(4), .criticas .cr:nth-child(5) { grid-column:span 3 }
.criticas .cr h4 { display:flex; align-items:center; gap:10px; color:var(--er); font-size:1.12em; margin-bottom:5px; line-height:1.25 }
.criticas .cr h4 .n-bola { background:var(--er) }
.criticas .cr p { margin:0; font-size:17.5px; line-height:1.4; color:var(--p) }
.criticas .cr.dec { background:var(--aviso-bg) } .criticas .cr.dec h4 { color:var(--aviso-tx) } .criticas .cr.dec h4 .n-bola { background:var(--aviso-tx) }
/* conclusões (slide 17) */
#s17 .kpi b { font-size:24px } #s17 .kpi > div { padding:9px 14px } #s17 .kpi span { font-size:14px }
#s17 .lin { padding:8px 16px } #s17 .lin div { font-size:16.5px }
#s17 .card.vd p { font-size:16px; line-height:1.45 }
/* referências (slide 18) */
.refs { list-style:none; margin:0; display:flex; flex-direction:column; justify-content:space-evenly; flex:1 }
#s18 .card { padding:16px 22px }
.sl .refs li { font-size:16.5px; line-height:1.35; margin:0; padding-left:20px }
/* cartões centralizados verticalmente e texto mais legível */
#s2 .card.vd, #s3 .card, #s7 .card, #s8 .card, #s11 .card, #s12 .card, #s13 .card, #s14 .card, #s15 .card, #s17 .card.vd { justify-content:center }
#s2 .card.vd p { font-size:18.5px; line-height:1.5 }
#s3 .card li { font-size:18px; margin:8px 0 } #s3 .card p { font-size:18px }
#s7 .card p { font-size:18px } #s14 .card p { font-size:17.5px; line-height:1.45 } #s8 .card li { font-size:18px; margin:7px 0 }
#s11 .card li, #s12 .card li, #s14 .card li, #s15 .card li { font-size:17.5px; margin:7px 0 }
#s12 .tb2 td, #s12 .tb2 th { font-size:17px }
/* modo roteiro (tecla N): slide compacto + notas legíveis na tela do apresentador */
body.notas .sl .slbd.g, body.notas .sl .slhd { zoom:.8 }
body.notas .sl .nt { font-size:14.5px; line-height:1.42; padding:9px 14px; max-height:40%; overflow:auto }
